import pandas as pd

def clean(df):
    df = df.copy()
    # standardise text variants
    if 'species' in df.columns:
        df['species'] = df['species'].astype(str).str.strip()
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip().str.title()
    # parse body_mass_g which is stored as text with commas
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # ensure numeric columns are numeric
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    sub = dfc.dropna(subset=['sex', 'body_mass_g'])
    means = sub.groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in means.items()}
